#!/usr/bin/env bash
# greenboot's required check on n1. The boot is declared successful only if
# the health predicate passes within 600s; on failure greenboot rolls back to
# the previous ostree deployment and the node reboots into it (§13.3).
#
# This is not a mechanism this repository invents. It is cited (§20.1),
# configured here, and tested in T2.
set -euo pipefail

if timeout 600s /usr/bin/cluster-health check; then
  exit 0
fi

# The predicate failed. Record the digest as quarantined before the rollback
# reboots us, so that no other node attempts it (§13.4). Quarantine is a
# precondition in §13.2, which is what stops the rollout rather than merely
# reporting on it.
digest="$(bootc status --json | jq -r '.status.booted.image.imageDigest')"
curl --silent --show-error --max-time 10 \
  --request POST "http://10.10.255.1:8080/api/rollout/quarantine" \
  --header 'content-type: application/json' \
  --data "{\"digest\":\"${digest}\",\"node\":\"n1\"}" || true

exit 1
